lemma component_locallyNilpotent {D : Derivation k R R} {j : ℤ}
    (hD : ShiftBound G D j) (hln : ∀ r : R, ∃ n : ℕ, (D : R → R)^[n] r = 0) :
    ∀ r : R, ∃ n : ℕ, (component G D j : R → R)^[n] r = 0

lemma nilpotent_add (D : Derivation k R R) {r s : R}
    (hr : ∃ n, (D : R → R)^[n] r = 0) (hs : ∃ n, (D : R → R)^[n] s = 0) :
    ∃ n, (D : R → R)^[n] (r+s) = 0

lemma nilpotent_mul (D : Derivation k R R) {r s : R}
    (hr : ∃ n, (D : R → R)^[n] r = 0) (hs : ∃ n, (D : R → R)^[n] s = 0) :
    ∃ n, (D : R → R)^[n] (r*s) = 0

theorem coeff_eq_zero_of_letter_ne {P : A α} {b a : α}
    (h : atom b * P = P * atom b) {w : List α} (ha : a ∈ w) (hab : a ≠ b) :
    P.coeff (FreeMonoid.ofList w) = 0

theorem dynkin_embed_word {n : ℕ} {p : FL α}
    (hp : WeightedWord (fun _ : α => 1) n p) :
    0 < n ∧ embed p ∈ homogeneous n ∧ dynkin (embed p) = (n : ℚ) • p

theorem bracket_homo {n m : ℕ} {p q : A K F}
    (hp : p∈homogeneous fiberCount n) (hq : q∈homogeneous fiberCount m) :
    bracket p q∈homogeneous fiberCount (n+m)

theorem diagonal_bracket {n m : ℕ} {p q : L} {s k t l : ℚ}
    (hn : 0 < n) (hm : 0 < m) (hp : DiagonalData n p s k) (hq : DiagonalData m q t l) :
    ∃ r : ℚ, DiagonalData (n+m) ⁅p,q⁆ 0 r

theorem diagonal_slope {n : ℕ} {p : L} {s k : ℚ}
    (hp : DiagonalData n p s k) (a t : M) :
    slope p a (-a) 0 t = k • adPower a (n-1) t

theorem kill_bound (a : α) (S : Finset α) (n : ℕ) {p : AQ α}
    (hp : p ∈ words (fun w => w.length≤n ∧ ∀ b ∈ w, b ∈ insert a S)) :
    kill a p ∈ words (fun w => w.length≤n ∧ ∀ b ∈ w, b ∈ S)

theorem operator_length (w : List (Option α)) {q : AQ (ℕ×α)} {n : ℕ}
    (hq : q ∈ words (fun v => v.length=n)) :
    operator (word w) q ∈ words (fun v => v.length=n+countSome w)

theorem remainder_bound (a : α) {p : AQ α} {n : ℕ}
    (hp : p ∈ words (fun w => w.length≤n)) :
    p-kill a p ∈ words (fun w => w.length≤n ∧ a ∈ w)

theorem rename_extract_lower (a : α) {p : AQ α} {n : ℕ}
    (hp : p ∈ words (fun w => w.length≤n+1 ∧ a ∈ w)) :
    extract (rename (tag a) p) ∈ words (fun w => w.length≤n)

theorem above_tmul {wa : α → ℕ} {wb : β → ℕ} {n m : ℕ} {p : A R α} {q : A R β}
    (hp : p∈WordGrading.above wa n) (hq : q∈WordGrading.above wb m) :
    p⊗ₜ q∈above wa wb (n+m)

theorem below_tmul {wa : α → ℕ} {wb : β → ℕ} {n m : ℕ} {p : A R α} {q : A R β}
    (hp : p∈WordGrading.below wa n) (hq : q∈WordGrading.below wb m) :
    p⊗ₜ q∈below wa wb (n+m)

theorem homo_tmul {wa : α → ℕ} {wb : β → ℕ} {n m : ℕ} {p : A R α} {q : A R β}
    (hp : p∈WordGrading.homogeneous wa n) (hq : q∈WordGrading.homogeneous wb m) :
    p⊗ₜ q∈homogeneous wa wb (n+m)

theorem strict_homo_tmul {wa : α → ℕ} {wb : β → ℕ} {n m : ℕ} {p : A R α} {q : A R β}
    (hp : p∈WordGrading.strictlyBelow wa n) (hq : q∈WordGrading.homogeneous wb m) :
    p⊗ₜ q∈strictlyBelow wa wb (n+m)

theorem eval_bounded (t : Tree α) {n : ℕ} {S : Finset α}
    (hn : t.leaves.length≤n) (hS : ∀ a ∈ t.leaves, a∈S) :
    (t.eval : FL R α) ∈ bounded n S

theorem Step.count_bound {κ : α → α → α → R} {r l : α} {s t : List α}
    (wt : α → ℕ) (c : ℕ) (hc : ∀ l a b,κ l a b≠0 → wt a≤c)
    (h : Step κ r l s t) : count wt s≤c+count wt t

theorem deriv_above {wt : α → ℕ} {c : ℕ} {f : α → A R α}
    (hf : ∀ a,f a∈above wt (wt a+c)) {n : ℕ} {p : A R α}
    (hp : p∈above wt n) : deriv f p∈above wt (n+c)

theorem deriv_below {wt : α → ℕ} {c : ℕ} {f : α → A R α}
    (hf : ∀ a,f a∈below wt (wt a+c)) {n : ℕ} {p : A R α}
    (hp : p∈below wt n) : deriv f p∈below wt (n+c)

theorem deriv_homogeneous {wt : α → ℕ} {c : ℕ} {f : α → A R α}
    (hf : ∀ a,f a∈homogeneous wt (wt a+c)) {n : ℕ} {p : A R α}
    (hp : p∈homogeneous wt n) : deriv f p∈homogeneous wt (n+c)

theorem deriv_strictlyBelow {wt : α → ℕ} {c : ℕ} {f : α → A R α}
    (hf : ∀ a,f a∈strictlyBelow wt (wt a+c)) {n : ℕ} {p : A R α}
    (hp : p∈homogeneous wt n) : deriv f p∈strictlyBelow wt (n+c)

theorem eval_quadratic {ψ : FreeLieAlgebra K Bool} {p : A K Slot}
    (hrep : embed ψ=quad p) (a b : Env S3) :
    BaseChangeEquations.eval a b ψ=quadEval a b p

theorem full_zero {ψ : FreeLieAlgebra K Bool} {p : A K Slot}
    (hrep : embed ψ=quad p) (hpent : BaseChangeEquations.pentagon ψ=0) :
    interpretation (full p)=0

theorem scalar_allocated (i : Row) (s : List Slot) {q : A K Slot}
    (hq : q∈homogeneous bCount (degree bCount (FreeMonoid.ofList s))) :
    scalar (κ₀ i) .o .w (FreeMonoid.ofList (s.map RowKernel.enc)) q=RowKernel.test i s q

theorem no_A_coeff {q : FreeLieAlgebra K Slot}
    (hq : LetterRetraction.lie (fun a => a≠Slot.A) q=0)
    (w : FreeMonoid Slot) (hw : degree RowKernel.aCount w=0) : (embed q).coeff w=0

theorem test_cut (i : Row) (s : List Slot) {p : A K Slot}
    (hp : p∈above aCount (degree aCount (FreeMonoid.ofList s))) :
    test i s p=scalar (cut (κ i) eCount aCount) .o .w (FreeMonoid.ofList (s.map enc)) p

theorem test_four (s : List Slot) {p : A K Slot}
    (hp : p∈above aCount (degree aCount (FreeMonoid.ofList s))) :
    test .four s p=p.coeff (FreeMonoid.ofList s)

theorem bracket_homo {n m : ℕ} {p q : A K F}
    (hp : p∈homogeneous fc n) (hq : q∈homogeneous fc m) :
    bracket p q∈homogeneous fc (n+m)

theorem Step.count_eq {κ : α → α → α → R} {r l : α} {s t : List α}
    (wt : α → ℕ) (c : ℕ) (hc : ∀ l a b,κ l a b≠0 → wt a=c)
    (h : Step κ r l s t) : count wt s=c+count wt t

theorem Step.count_lower {κ : α → α → α → R} {r l : α} {s t : List α}
    (wt : α → ℕ) (c : ℕ) (hc : ∀ l a b,κ l a b≠0 → c≤wt a)
    (h : Step κ r l s t) : c+count wt t≤count wt s

theorem Step.count_strict {κ : α → α → α → R} {r l : α} {s t : List α}
    (wt : α → ℕ) (c : ℕ) (hc : ∀ l a b,κ l a b≠0 → wt a<c)
    (h : Step κ r l s t) : count wt s<c+count wt t

theorem totalPiece_homogeneous {k : ℕ} {p : A R α⊗[R]A R β}
    (hp : p∈TensorGrading.homogeneous (fun _ => 1) (fun _ => 1) k) (n : ℕ) :
    totalPiece n p=if k=n then p else 0

theorem linear_ideal {B : Type*} [CommRing B] (h c a b r q W : B)
    (hc : c*a = h*b) (hb : r*h+q*c = 1) :
    Ideal.span ({h*W-a, c*W-b} : Set B) = Ideal.span {W-(r*a+q*b)}

lemma bounds_of_weight {w : ℤ → ℝ} (hw : ∀ j, 0 < w j) {b c : ℤ → ℂ}
    (hb : ∀ j, ‖b j‖ ≤ w j) (hc : ∀ j, ‖c j‖ * w j ≤ 1) :
    EnvelopeBounds (negativeLog w) (positiveLog w) b c

lemma nat_support_unbounded {d : ℤ → ℂ}
    (hu : ¬∃ m : ℤ, ∀ j : ℤ, d j ≠ 0 → j ≤ m) :
    ∀ n : ℕ, ∃ k, n < k ∧ d (k:ℤ) ≠ 0

lemma reflected_correlations {b c : ℤ → ℂ}
    (hz : ∀ r : ℕ, 1 ≤ r → (∑' j : ℤ, b j * c (j-r)) = 0) :
    ∀ r : ℕ, 1 ≤ r → (∑' j : ℤ, c (-j) * b (-(j-r))) = 0

lemma ergodic_completion {α : Type*} [MeasurableSpace α] {μ : Measure α}
    {f : α → α} (hf : Ergodic f μ) :
    @Ergodic (NullMeasurableSpace α μ) _ f μ.completion

lemma measurePreserving_completion {α : Type*} [MeasurableSpace α] {μ : Measure α}
    {f : α → α} (hf : MeasurePreserving f μ μ) :
    @MeasurePreserving (NullMeasurableSpace α μ) (NullMeasurableSpace α μ) _ _
      f μ.completion μ.completion

lemma halfSum_eventually_affine {t u : ℕ → ℕ} {d : ℝ}
    (hd : ∀ᶠ k : ℕ in atTop, halfExponent u k-halfExponent t k = d) :
    ∃ C : ℝ, ∀ᶠ n : ℕ in atTop, halfSum u n-halfSum t n = d*(n:ℝ)+C

lemma StronglyClosed.mem_of_tendsto {A : StarSubalgebra ℂ (H →L[ℂ] H)}
    (hA : StronglyClosed A) {ι : Type*} {l : Filter ι} [l.NeBot]
    {T : ι → H →L[ℂ] H} {S : H →L[ℂ] H}
    (hT : ∀ᶠ i in l, T i ∈ A) (hlim : ∀ v, Tendsto (fun i => T i v) l (𝓝 (S v))) :
    S ∈ A

lemma strongGenerated_commutative {s : Set (H →L[ℂ] H)}
    (hs : ∀ A ∈ s, IsSelfAdjoint A) (hc : ∀ A ∈ s, ∀ B ∈ s, A*B=B*A) :
    ∀ A ∈ strongGenerated s, ∀ B ∈ strongGenerated s, A*B=B*A

lemma eigenspace_projection_minimal {s : Set (H →L[ℂ] H)}
    (hs : ∀ T ∈ s, IsSelfAdjoint T) {P : H →L[ℂ] H}
    (hP : IsStarProjection P) (hP₀ : P ≠ 0) (hPA : P ∈ strongGenerated s)
    (hscalar : ∀ T ∈ s, ∃ t : ℝ, ∀ v : H, P v = v → T v = (t:ℂ) • v) :
    MinimalProjection (strongGenerated s) P

lemma ae_prod_count_iff {X : Type*} [MeasurableSpace X] {μ : Measure X}
    {p : X × ℤ → Prop} (hp : MeasurableSet {z | p z}) :
    (∀ᵐ z ∂μ.prod Measure.count, p z) ↔ ∀ᵐ x ∂μ, ∀ j : ℤ, p (x,j)

@[simp] theorem AdmissibleList.eval_apply {L : Set (S → ℝ)} {C : ℝ≥0}
    (l : AdmissibleList L C) (p : ℝ≥0∞) (m : Molecule S) (i : Fin l.length) :
    (l.eval p m) i = pairing S (l.test i) m

@[simp] theorem AdmissibleList.seminorm_apply {L : Set (S → ℝ)} {C : ℝ≥0}
    (l : AdmissibleList L C) (p : ℝ≥0∞) [Fact (1 ≤ p)] (m : Molecule S) :
    l.seminorm p m = ‖l.eval p m‖

theorem AdmissibleList.seminorm_le {L : Set (S → ℝ)} {C : ℝ≥0}
    (l : AdmissibleList L C) (p : ℝ≥0∞) [Fact (1 ≤ p)] (o : S) (m : Molecule S) :
    l.seminorm p m ≤ C * ∑ s ∈ m.val.support, |m.val s| * dist s o

theorem AdmissibleList.seminorm_molecule_le {L : Set (S → ℝ)} {C : ℝ≥0}
    (l : AdmissibleList L C) (p : ℝ≥0∞) [Fact (1 ≤ p)] (s t : S) :
    l.seminorm p (molecule s t) ≤ C * dist s t

theorem AdmissibleList.sum_abs_sub_le {L : Set (S → ℝ)} {C : ℝ≥0}
    (l : AdmissibleList L C) (s t : S) :
    ∑ i, |l.test i s - l.test i t| ≤ C * dist s t

theorem cutoff_dist_le {X : Type*} [PseudoMetricSpace X] (q : X) {ε : ℝ}
    (hε : 0 < ε) (x y : X) :
    |cutoff q ε x-cutoff q ε y| ≤ (2 / ε) * dist x y

theorem lipschitzOn_convex_of_local {E Y : Type*}
    [NormedAddCommGroup E] [NormedSpace ℝ E] [PseudoMetricSpace Y]
    {B : Set E} (hB : Convex ℝ B) {f : E → Y} {K : ℝ≥0}
    (hf : ContinuousOn f B)
    (hloc : ∀ x ∈ B, ∀ᶠ y in nhdsWithin x B, dist (f x) (f y) ≤ K * dist x y) :
    LipschitzOnWith K f B

theorem lipschitz_convex_subtype_of_local {E Y : Type*}
    [NormedAddCommGroup E] [NormedSpace ℝ E] [PseudoMetricSpace Y]
    {B : Set E} (hB : Convex ℝ B) {f : B → Y} {K : ℝ≥0}
    (hf : Continuous f)
    (hloc : ∀ x, ∀ᶠ y in nhds x, dist (f x) (f y) ≤ K * dist x y) :
    LipschitzWith K f

theorem localG_lipschitz {X : Type*} [PseudoMetricSpace X] (q : X) {ε : ℝ}
    (hε : 0 < ε) (u : X → ℝ) {L : ℝ≥0} (hu : LipschitzWith L u) :
    LipschitzWith (4*L) (localG q ε u)

theorem localR_lipschitz {X : Type*} [PseudoMetricSpace X] (q : X) {ε : ℝ}
    (hε : 0 < ε) (u : X → ℝ) {L : ℝ≥0} (hu : LipschitzWith L u) :
    LipschitzWith (3*L) (localR q ε u)

theorem localR_sup_lip {X : Type*} [PseudoMetricSpace X] (q : X) {ε : ℝ}
    (hε : 0 < ε) (u : X → ℝ) {L : ℝ≥0} (hu : LipschitzWith L u) (x : X) :
    |localR q ε u x| ≤ ε * L

theorem length_le_of_prefix (r : GeneratedRepresentation B γ)
    (pre suf : List (CylinderOperation (B.coordinates γ))) (he : r.operations=pre++suf) {h : ℕ}
    (hh : r.operations.length ≤ h) : pre.length ≤ h

theorem full_tail_support (f : C0Ball → ℝ) (ts : List TailOperation) (t : TailOperation)
    (ht : t ∈ ts) (hg : t.isBasic=false) :
    tsupport (fun s => f s*tailProduct ts s) ⊆ {s | dyadic t.scaleIndex ≤ tau (t.tailIndex+1) s.val}

theorem correction_weight_error {W V : FrozenWeights} {x : C0} {q : ℝ}
    (hq : 0≤q) (h : WeightError W V x q) (γ : Label) :
    |frozenCorrection W γ x-frozenCorrection V γ x|≤6*q

theorem previousScalar_weight_error {W V : FrozenWeights} {x : C0} {q : ℝ}
    (hq : 0≤q) (h : WeightError W V x q) (lev : Level) :
    |previousScalar W lev x-previousScalar V lev x|≤q

theorem fiveBounds_of_error {E : Type*} [NormedAddCommGroup E] {a b : E} {d e : ℝ}
    (he : ‖a-b‖≤e*d) (hU : ‖b‖≤5*d) (hL : d≤5*‖b‖) :
    (1/5-e)*d≤‖a‖ ∧ ‖a‖≤(5+e)*d

lemma D_outer_bddAbove (hinf : ¬ FiniteDimensional ℝ X) {x : X} (hx : ‖x‖ = 1)
    {t : ℝ} (ht : 0 ≤ t) :
    BddAbove {r | ∃ F : Submodule ℝ X, Cofinite F ∧ r = sInf (oneSidedValues x t F)}

lemma H_outer_bddAbove (hinf : ¬ FiniteDimensional ℝ X) {x : X} (hx : ‖x‖ = 1)
    {t : ℝ} (ht : 0 ≤ t) :
    BddAbove {r | ∃ F : Submodule ℝ X, Cofinite F ∧ r = sInf (averageValues x t F)}

lemma cofinite_has_Nunit (hinf : ¬ FiniteDimensional ℝ X) {N : Seminorm ℝ X}
    (hN : EquivalentNorm N) {F : Submodule ℝ X} (hF : Cofinite F) :
    ∃ y ∈ F, N y = 1

lemma normD_centers_bddBelow (hinf : ¬ FiniteDimensional ℝ X) {N : Seminorm ℝ X}
    (hN : EquivalentNorm N) {t : ℝ} (ht : 0 ≤ t) :
    BddBelow {r | ∃ x : X, N x = 1 ∧ r = D N x t}

lemma normD_outer_bddAbove (hinf : ¬ FiniteDimensional ℝ X) {N : Seminorm ℝ X}
    (hN : EquivalentNorm N) {x : X} (hx : N x = 1) {t : ℝ} (ht : 0 ≤ t) :
    BddAbove {r | ∃ F : Submodule ℝ X, Cofinite F ∧ r = sInf (normOneSidedValues N x t F)}

lemma normOneSidedValues_nonempty (hinf : ¬ FiniteDimensional ℝ X) {N : Seminorm ℝ X}
    (hN : EquivalentNorm N) (x : X) (t : ℝ) {F : Submodule ℝ X} (hF : Cofinite F) :
    (normOneSidedValues N x t F).Nonempty

lemma seminorm_segment_le (N : Seminorm ℝ X) {x y : X} {r M : ℝ}
    (hr : 0 ≤ r) (hr' : r ≤ 1) (hx : N x ≤ M) (hy : N y ≤ M) :
    N ((1 - r) • x + r • y) ≤ M

lemma difference_tail_lower {p u : ℝ} (hp : 1 < p) (hpmax : p ≤ 3 / 2)
    (hu : scale p ≤ u) :
    (1 / 18) * (scale p / u) ^ p ≤ pairedMeasure.real {v | u < |difference p v|}

lemma integral_hardTruncate_zero [IsProbabilityMeasure μ] {X : Ω → ℝ} {u : ℝ}
    (hsym : IdentDistrib X (fun ω => -X ω) μ μ) :
    ∫ ω, hardTruncate u (X ω) ∂μ = 0

lemma integral_min_abs_sq {X : Ω → ℝ} (hX : Measurable X) {u : ℝ} (hu : 0 < u) :
    ∫ ω, (min |X ω| u) ^ 2 ∂μ =
      ∫ t in Ioc 0 u, 2 * t * μ.real {ω | t < |X ω|}

lemma difference_law_tail [IsProbabilityMeasure μ] {Y : Ω → ℝ} {p u : ℝ}
    (hY : IdentDistrib Y (difference p) μ pairedMeasure) :
    μ.real {ω | u < |Y ω|} = pairedMeasure.real {v | u < |difference p v|}

lemma scaled_difference_symmetric [IsProbabilityMeasure μ] {Y : Ω → ℝ} {p : ℝ}
    (hY : IdentDistrib Y (difference p) μ pairedMeasure) (a : ℝ) :
    IdentDistrib (fun ω => a * Y ω) (fun ω => -(a * Y ω)) μ μ

lemma scaled_difference_tail_lower {Y : Ω → ℝ} {p u : ℝ}
    (hp : 1 < p) (hpmax : p ≤ 3 / 2) (hY : IdentDistrib Y (difference p) μ pairedMeasure)
    (a : ℝ) (hu : 0 < u) (husa : scale p * |a| ≤ u) :
    (1 / 18) * (scale p * |a|) ^ p * u ^ (-p) ≤ μ.real {ω | u < |a * Y ω|}

lemma concentration_center {R : Type uR} [MeasurableSpace R] {ν : Measure R}
    [IsProbabilityMeasure ν] {z : R → ℝ} (hz : Measurable z) {r q : ℝ}
    (h : (ν.prod ν).real {v | r < |z v.1 - z v.2|} < q) :
    ∃ c : ℝ, ν.real {v | r < |z v - c|} < q

lemma diffRowSum_prod_tail (p : ℝ) (a : ι → ℝ) (r : ℝ) :
    ((cubeMeasure ι).prod (cubeMeasure ι)).real {v | r < |rowSum p a v.1 - rowSum p a v.2|} =
      (pairCubeMeasure ι).real {v | r < |diffRowSum p a v|}

lemma measurable_enlargedFunction (p : ℝ) {x : B → ℝ} {u : κ → B → ℝ}
    (hx : Measurable x) (hu : ∀ k, Measurable (u k)) (a : κ → ι → ℝ) :
    Measurable (enlargedFunction p x u a)

lemma integrable_oldCombination [IsProbabilityMeasure μ] {x : B → ℝ} {u : κ → B → ℝ}
    (hx : Integrable x μ) (hu : ∀ k, Integrable (u k) μ) (c : κ → ℝ) :
    Integrable (oldCombination x u c) μ

lemma normalizeL1_approx {B : Type uB} [MeasurableSpace B] {μ : Measure B}
    (x y : Lp ℝ 1 μ) (hx : ‖x‖ ≤ 1) :
    ‖x - normalizeL1 y‖ ≤ 2 * ‖x-y‖

lemma gate_unique_in_segment {H : Set ι} {S : Finset ι}
    (hS : A.segments.IsSegment S) {g h : ι} (hg : A.Gate H g)
    (hh : A.Gate H h) (hgS : g ∈ S) (hhS : h ∈ S) : g = h

lemma tailAt_allowed (F : A.segments.Family) {H : Finset ι}
    (hH : A.Ancestral (H : Set ι)) (g : ι) (hne : (A.tailAt F H g).Nonempty) :
    A.segments.IsSegment (A.tailAt F H g)

lemma tailAt_pairwise {κ : Type*} (F : κ → A.segments.Family) {H : Finset ι}
    (gate : κ ↪ ι) (hg : ∀ a, A.Gate (H : Set ι) (gate a)) :
    Pairwise (fun a b => Disjoint (A.tailAt (F a) H (gate a)) (A.tailAt (F b) H (gate b)))

lemma finite_square_tails (a : ι → ℝ) {M : ℝ}
    (hM : ∀ S : Finset ι,(∑ v ∈ S,a v^2) ≤ M) {δ : ℝ} (hδ : 0 < δ) :
    ∃ S : Finset ι, ∀ U : Finset ι, Disjoint S U → (∑ v ∈ U,a v^2) < δ

lemma deviation_separated {n : ℕ} (f : Vertex (n+1) → X) {s : ℝ}
    (hl : ∀ u v,s*distance (n+1) u v ≤ ‖f u-f v‖) (e : Edge n)
    {i j : ℕ} (hij : i ≠ j) : 2*s ≤ ‖deviation f e i-deviation f e j‖

lemma normalized_distortion {k : ℕ} (f : Vertex k → X) {D s : ℝ}
    (h : HasDistortion k f D s) :
    HasDistortion k (fun v => s⁻¹ • f v) D 1

lemma old_lower {X : Type*} [NormedAddCommGroup X] [NormedSpace ℝ X] {k : ℕ} (f : Vertex (k+1) → X) {s : ℝ}
    (hl : ∀ u v,s*distance (k+1) u v ≤ ‖f u-f v‖) :
    ∀ u v,s*distance k u v ≤ ‖f (Sum.inl u)-f (Sum.inl v)‖

theorem Heads.parametric_lens (A : Heads ι X) {a b lam : ℝ}
    (ha : 0 < a) (hb : 0 < b) (hlam : 0 < lam) (hinput : A.ParametricInput a b)
    {x : X} (z : ℕ → X) {R ε : ℝ}
